112. /// - `mmio_regions`: Memory-mapped I/O regions to book.
113. /// - `physical_memory_layout`: Physical memory layout bitmap.
114. ///
115. /// # Returns
116. ///
117. /// Upon success, `Ok(())` is returned. Upon failure, an error is returned instead.
118. ///
