120.     physical_memory_regions: LinkedList<TruncatedMemoryRegion<PhysicalAddress>>,
121.     mmio_regions: &LinkedList<TruncatedMemoryRegion<VirtualAddress>>,
122.     physical_memory_layout: Bitmap,
123. ) -> Result<(), Error> {
124.     // Initialize frame allocator singleton.
