133.     info!("initializing the user page pool ...");
134.     let upool: Upool = Upool::new();
135. 
136.     // Initialize physical memory manager singleton.
137.     info!("initializing the physical memory manager ...");
138.     PhysMemoryManager::init(upool)?;
139. 
140.     Ok(())
141. }
