545.                 let frame_numbers = vstd::set_lib::set_int_range(start_frame_number, end_frame_number);
546.                 let frames = frame_numbers.map(|i: int| i * spec_page_size());
547.                 match result {
548.                     Ok(()) => {
549.                         &&& frames.subset_of(old(self)@.free_frames)
550.                         &&& final(self)@ == FrameAllocView {
551.                             allocated_frames: old(self)@.allocated_frames.union(frames),
552.                             free_frames: old(self)@.free_frames.difference(frames),
553.                             refcounts: old(self)@.refcounts.union_prefer_right(
554.                                 Map::new(|addr: int| frames.contains(addr), |addr: int| 1int)
555.                             ),
556.                         }
557.                     },
558.                     Err(_) => {
559.                         &&& final(self)@ == old(self)@
560.                         &&& !frames.subset_of(old(self)@.free_frames)
561.                     },
562.                 }
563.             }),
564.     )]
